param([Parameter(Mandatory)][string]$Output)
$ErrorActionPreference='Stop'
if(Test-Path -LiteralPath $Output){throw 'Preserve toolchain receipt'}
$commands=@{};foreach($n in @('cl.exe','nmake.exe','dumpbin.exe','cmake.exe','ninja.exe','MSBuild.exe','dotnet.exe')){$c=Get-Command $n -ErrorAction SilentlyContinue;$commands[$n]=if($c){$c.Source}else{$null}}
$registry=foreach($p in @('HKLM:/SOFTWARE/Microsoft/VisualStudio/SxS/VS7','HKLM:/SOFTWARE/WOW6432Node/Microsoft/VisualStudio/SxS/VS7','HKLM:/SOFTWARE/Microsoft/Windows Kits/Installed Roots','HKLM:/SOFTWARE/WOW6432Node/Microsoft/Windows Kits/Installed Roots')){@{path=$p;exists=Test-Path $p;properties=$(if(Test-Path $p){Get-ItemProperty $p}else{$null})}}
$vswhere='C:/Program Files (x86)/Microsoft Visual Studio/Installer/vswhere.exe';$vs=@();if(Test-Path $vswhere){$vs=(& $vswhere -all -products '*' -format json|ConvertFrom-Json)}
$candidates=@('C:/Program Files/Microsoft Visual Studio','C:/Program Files (x86)/Microsoft Visual Studio','C:/BuildTools','D:/BuildTools','E:/BuildTools','D:/VisualStudio','D:/Microsoft Visual Studio','E:/Microsoft Visual Studio','C:/Program Files (x86)/Windows Kits/10/Include','C:/Program Files (x86)/Windows Kits/10/Lib');$paths=@($candidates|ForEach-Object {@{path=$_;exists=Test-Path -LiteralPath $_}})
$missing=@();foreach($n in @('cl.exe','nmake.exe','dumpbin.exe')){if(!$commands[$n]){$missing+=$n}};if(!$env:WindowsSdkDir -or !(Test-Path -LiteralPath (Join-Path $env:WindowsSdkDir 'Include'))){$missing+='Windows SDK include/lib registered and active'};if($env:VSCMD_ARG_TGT_ARCH -ne 'x64'){$missing+='x64 MSVC Developer shell'}
@{status=$(if($missing.Count){'REQUIRED_MSVC_TOOLCHAIN_UNAVAILABLE'}else{'MSVC_PREFLIGHT_FOUND_REQUIRES_BUILD_VALIDATION'});commands=$commands;registry=$registry;vswhereExists=Test-Path $vswhere;visualStudioInstances=$vs;candidatePaths=$paths;missing=$missing;currentDeveloperShell=@{target=$env:VSCMD_ARG_TGT_ARCH;vcTools=$env:VCToolsInstallDir;sdk=$env:WindowsSdkDir};alternateExistingCompiler='D:/Tools/REA/zig-x86_64-windows-0.15.2/zig.exe exists; not MSVC/Windows SDK, not used as substitute DLL toolchain';rawCalls=0;nativeBuildAttempts=0;timeAsiaShanghai=[TimeZoneInfo]::ConvertTimeBySystemTimeZoneId([DateTimeOffset]::UtcNow,'China Standard Time').ToString('o')}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $Output
